export function assertReviewedImage(root,reviewedCommit,files){
 check(/^[0-9a-f]{40}$/.test(reviewedCommit)&&Array.isArray(files)&&files.length>0&&new Set(files).size===files.length,'FIXTURE_REVIEWED_SOURCE_IMAGE_REQUIRED');
 const head=git(root,'rev-parse','HEAD').toString().trim();
 try{git(root,'merge-base','--is-ancestor',reviewedCommit,head);}catch{throw Error('FIXTURE_REVIEWED_SOURCE_ANCESTRY_REQUIRED');}
 for(const file of files){
  check(typeof file==='string'&&/^[A-Za-z0-9_./-]+$/.test(file)&&!file.split('/').includes('..')&&!file.startsWith('/'),'FIXTURE_REVIEWED_SOURCE_PATH_REQUIRED');
  check(same(root,file,head).equals(git(root,'show',reviewedCommit+':'+file)),'FIXTURE_REVIEWED_SOURCE_IMAGE_CHANGED');
 }
 return {reviewedCommit,executionCommit:head,selectedImagesUnchanged:true};
}
